import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { Link, useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { toast } from 'sonner'
import { supabaseAuthService } from '@/integrations/supabase/auth'

const schema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
  confirmPassword: z.string(),
}).refine((d) => d.password === d.confirmPassword, {
  message: 'Passwords do not match',
  path: ['confirmPassword'],
})

type FormData = z.infer<typeof schema>

export function SignupPage() {
  const { t } = useTranslation('auth')
  const navigate = useNavigate()

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<FormData>({ resolver: zodResolver(schema) })

  const onSubmit = async (data: FormData) => {
    try {
      await supabaseAuthService.signUpWithEmail(data.email, data.password)
      toast.success('Account created! Check your email to confirm.')
      navigate('/auth/login')
    } catch (e) {
      toast.error((e as Error).message || t('errors.signupFailed'))
    }
  }

  return (
    <div className="bg-surface rounded-2xl border border-border p-8 shadow-sm">
      <h1 className="text-xl font-semibold mb-1">{t('signupTitle')}</h1>
      <p className="text-sm text-muted-foreground mb-6">{t('signupSubtitle')}</p>

      <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col gap-4">
        <div>
          <label className="text-sm font-medium block mb-1.5">{t('email')}</label>
          <input {...register('email')} type="email" className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
          {errors.email && <p className="text-xs text-danger mt-1">{errors.email.message}</p>}
        </div>
        <div>
          <label className="text-sm font-medium block mb-1.5">{t('password')}</label>
          <input {...register('password')} type="password" className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
          {errors.password && <p className="text-xs text-danger mt-1">{errors.password.message}</p>}
        </div>
        <div>
          <label className="text-sm font-medium block mb-1.5">{t('confirmPassword')}</label>
          <input {...register('confirmPassword')} type="password" className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
          {errors.confirmPassword && <p className="text-xs text-danger mt-1">{errors.confirmPassword.message}</p>}
        </div>
        <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-accent-foreground rounded-lg py-2.5 text-sm font-medium hover:opacity-90 disabled:opacity-50">
          {isSubmitting ? '...' : t('createAccount')}
        </button>
      </form>

      <p className="text-center text-xs text-muted-foreground mt-4">
        {t('alreadyHaveAccount')}{' '}
        <Link to="/auth/login" className="text-accent hover:underline">{t('login')}</Link>
      </p>
    </div>
  )
}
